(()=>{
/* Bài 3 — Câu lệnh if, if–else (chuẩn tường minh, 19/10/2026)
   Bối cảnh: quầy trà sữa của lớp tại Lễ hội Mùa Xuân. Tiết 1 = Chặng 1 (if, tiết thao giảng 28/10/2026 lớp 8A8),
   tiết 2 = Chặng 2 (if–else) và Chặng chứng chỉ. Mỗi chặng 6 tab (VAN_PHONG.md):
   Bối cảnh → Đoán rồi chạy → Kiểm chứng → Ghi nhớ → Luyện tập → Phản tư.
   Chuẩn câu hỏi: có tình huống, hỏi một ý, 4 phương án độ dài gần bằng nhau; mỗi phương án sai là một cách hiểu sai thường gặp.
   Bước chạy có bảng Bộ nhớ (mem), số nhập tô vàng (nhap) và dòng điều kiện tô xanh/đỏ (kq: "t" đúng, "f" sai).
   Giữ nguyên mã nhiệm vụ (c1-dc5, c1-dc2, c1-dc3, …) vì giáo án và slide thao giảng dẫn chiếu theo thứ tự 5, 2, 3 ly.
*/
"use strict";

const { scratch, boiCanh, bang, ghiVo, luuY, chiTiet, timThem, sauTab, huongDanDoan, bonBuoc, tuCham } = window.KIT;
const strip = code => window.CPP.stripComments(code);

/* ---------- đoạn code dùng xuyên suốt ---------- */
// Chặng 1: điều kiện viết sai mốc (> thay vì >=): khách mua đúng 3 ly không được tặng.
const TOPPING = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    if (soLy > 3) {
        cout << "Tang topping" << endl;
    }
    cout << "Cam on quy khach!";
    return 0;
}`;
const manTopping = (n, tang) => `Nhap so ly: ${n}\n${tang ? "Tang topping\n" : ""}Cam on quy khach!`;
const luaChonTopping = n => [manTopping(n, true), manTopping(n, false), `Nhap so ly: ${n}\nTang topping`, `Nhap so ly: ${n}\nCam on quy khach!\nTang topping`];
const traceTopping = n => {
  const dung = n > 3;
  return [
    { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
    { l: 4, mem: ["soLy", "int", "?"], why: "Khai báo biến <code>soLy</code> để lưu số ly khách mua. Chưa có giá trị." },
    { l: 5, out: "Nhap so ly: ", why: "In câu dẫn để khách biết cần gõ gì." },
    { l: 6, nhap: String(n), mem: ["soLy", "int", String(n)], why: `Máy dừng chờ. Khách gõ <code>${n}</code> rồi bấm Enter, <code>cin</code> lưu ${n} vào <code>soLy</code>.` },
    { l: 7, kq: dung ? "t" : "f", why: `Máy tính <strong>điều kiện</strong> <code>soLy &gt; 3</code>, tức là <code>${n} &gt; 3</code>: ${dung ? `${n} lớn hơn 3, nên điều kiện <strong>đúng</strong>. Máy vào khối <code>{ }</code>.` : `${n} ${n === 3 ? "bằng 3, không lớn hơn 3" : "nhỏ hơn 3"}, nên điều kiện <strong>sai</strong>. Máy bỏ qua cả khối <code>{ }</code> (dòng 8) và nhảy tới sau dấu <code>}</code>.`}` },
    ...(dung ? [{ l: 8, out: "Tang topping\n", why: "Dòng 8 nằm trong khối <code>{ }</code> của if, chỉ chạy khi điều kiện đúng." }] : []),
    { l: 10, out: "Cam on quy khach!", why: "Dòng 10 nằm <strong>sau</strong> dấu <code>}</code> của khối if, nên luôn chạy, dù điều kiện đúng hay sai." },
    { l: 11, why: "<code>return 0;</code> kết thúc chương trình." }];
};

// Chặng 2: if–else chọn quà theo mốc 5 ly.
const QUA = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    if (soLy >= 5) {
        cout << "Tang banh" << endl;
    } else {
        cout << "Tang keo" << endl;
    }
    cout << "Cam on quy khach!";
    return 0;
}`;
const manQua = (n, qua) => `Nhap so ly: ${n}\n${qua}Cam on quy khach!`;
const luaChonQua = n => [manQua(n, "Tang banh\n"), manQua(n, "Tang keo\n"), manQua(n, "Tang banh\nTang keo\n"), manQua(n, "")];
const traceQua = n => {
  const dung = n >= 5;
  return [
    { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
    { l: 4, mem: ["soLy", "int", "?"], why: "Khai báo biến <code>soLy</code>, chưa có giá trị." },
    { l: 5, out: "Nhap so ly: ", why: "In câu dẫn." },
    { l: 6, nhap: String(n), mem: ["soLy", "int", String(n)], why: `Khách gõ <code>${n}</code> rồi bấm Enter, <code>cin</code> lưu ${n} vào <code>soLy</code>.` },
    { l: 7, kq: dung ? "t" : "f", why: `Máy tính điều kiện <code>${n} &gt;= 5</code>: ${dung ? `${n} ${n === 5 ? "bằng 5" : "lớn hơn 5"}, nên điều kiện <strong>đúng</strong>. Máy chạy nhánh if.` : `${n} nhỏ hơn 5, nên điều kiện <strong>sai</strong>. Máy bỏ qua nhánh if và chạy nhánh else.`}` },
    ...(dung
      ? [{ l: 8, out: "Tang banh\n", why: "Nhánh if: in <code>Tang banh</code>. Nhánh else (dòng 10) bị bỏ qua, vì mỗi lần chỉ chạy một nhánh." }]
      : [{ l: 9, why: "Điều kiện sai nên máy nhảy tới <code>else</code>. <code>else</code> không có điều kiện riêng: nó là phần còn lại khi điều kiện if sai." },
         { l: 10, out: "Tang keo\n", why: "Nhánh else: in <code>Tang keo</code>." }]),
    { l: 12, out: "Cam on quy khach!", why: "Dòng 12 nằm sau dấu <code>}</code> cuối cùng của if–else, nên luôn chạy." },
    { l: 13, why: "<code>return 0;</code> kết thúc chương trình." }];
};

const PHI_GIAO_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int tongTien;
    cout << "Nhap tong tien: ";
    cin >> tongTien;
    // Viet if - else o day

    cout << "Cam on quy khach!";
    return 0;
}`;
const HANG_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int diem;
    cout << "Nhap diem: ";
    cin >> diem;
    // Viet if - else o day

    cout << "Cam on quy khach!";
    return 0;
}`;

const doanChay = (id, lan, n, after, whyRight, why) => ({
  id, type: "doanchay", predict: true, icon: "🔮", after,
  title: `Lần ${lan} · Khách mua ${n === 3 ? "đúng " : ""}${n} ly`,
  prompt: `Quy tắc của quầy: mua <strong>từ 3 ly trở lên</strong> được tặng topping. Chương trình bên trái là máy tính tiền hiện tại. Khi máy chờ ở dòng 6, khách gõ <code>${n}</code>.`,
  ask: "Theo bạn, màn hình sẽ hiện gì?",
  code: TOPPING, focus: [7], input: String(n), options: luaChonTopping(n), answer: manTopping(n, n > 3),
  trace: traceTopping(n), whyRight, why });
const doanQua = (id, lan, n, after, whyRight, why) => ({
  id, type: "doanchay", predict: true, icon: "🔮", after,
  title: `Lần ${lan} · Khách mua ${n === 5 ? "đúng " : ""}${n} ly`,
  prompt: `Quy tắc mới: mua <strong>từ 5 ly trở lên</strong> tặng bánh, dưới 5 ly tặng kẹo. Khi máy chờ ở dòng 6, khách gõ <code>${n}</code>.`,
  ask: "Theo bạn, màn hình sẽ hiện gì?",
  code: QUA, focus: [7, 9], input: String(n), options: luaChonQua(n), answer: manQua(n, n >= 5 ? "Tang banh\n" : "Tang keo\n"),
  trace: traceQua(n), whyRight, why });

const BON_BUOC_1 = bonBuoc([["Hiểu đề", "nhập gì, in gì, quy tắc nói “từ … trở lên”, “trên” hay “dưới”?"],
  ["Chọn biến", "biến lưu số nhập, kiểu <code>int</code>, tên có nghĩa."],
  ["Thiết kế test case trước khi viết", "một số dưới mốc, một số đúng mốc, một số trên mốc; tính tay màn hình mong đợi."],
  ["Viết, chạy, so sánh, sửa", "chạy với từng test case, so màn hình với kết quả đã tính tay."]]);

window.LESSON = {
  id: "bai03",
  chuan: 2,
  number: 3,
  title: "Câu lệnh if, if–else",
  story: "Quầy trà sữa Lễ hội Mùa Xuân",
  badge: { icon: "🧋", name: "Người giữ đúng khuyến mãi" },
  skills: ["Phép so sánh", "Câu lệnh if", "Khối lệnh { }", "if–else", "Kiểm thử đúng mốc", "Đọc lỗi logic"],
  certNote: "Nộp kèm: ảnh bài làm nhóm và bài cá nhân trên Programiz",

  errorTable: [
    ["Khách đúng mốc không được khuyến mãi", "Dùng <code>&gt;</code> trong khi quy tắc nói “từ … trở lên”", "Dùng <code>&gt;=</code>; luôn thử đúng số mốc"],
    ["Khối <code>{ }</code> chạy với mọi khách", "Có dấu <code>;</code> ngay sau <code>if (…)</code>", "Xoá dấu <code>;</code> đứng sau dấu <code>)</code>"],
    ["Điều kiện bằng luôn đúng hoặc báo lỗi", "Viết <code>=</code> (phép gán) thay vì <code>==</code> (so sánh bằng)", "So sánh bằng dùng <code>==</code>"],
    ["Lỗi cú pháp ở dòng else", "Viết điều kiện sau <code>else</code>", "<code>else</code> không có điều kiện: <code>} else {</code>"],
    ["Lời cảm ơn chỉ in cho một số khách", "Đặt câu lệnh cảm ơn bên trong khối <code>{ }</code>", "Đưa câu lệnh ra sau dấu <code>}</code> cuối cùng"],
    ["Máy báo không biết tên “cout”", "Thiếu <code>using namespace std;</code>", "Thêm ngay sau <code>#include &lt;iostream&gt;</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · if ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · PHÉP SO SÁNH VÀ CÂU LỆNH if",
      title: "Tặng topping đúng quy tắc",
      bit: "Chào bạn! Chặng này có 6 phần. Làm xong mỗi phần, bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Viết điều kiện bằng phép so sánh, phân biệt > và >=",
        "Chỉ ra câu lệnh nào chạy khi điều kiện đúng, câu lệnh nào luôn chạy",
        "Kiểm thử chương trình bằng test case dưới, đúng và trên mốc"],
      flow: [
        { label: "Bối cảnh", title: "Khách mua đúng 3 ly mà không được tặng topping",
          html: boiCanh("Quy tắc của quầy: khách mua từ 3 ly trở lên được tặng topping. Hôm qua, một khách mua đúng 3 ly nhưng máy tính tiền không in “Tang topping”.",
            `<p>Đến giờ, chương trình của lớp mình luôn chạy mọi câu lệnh từ trên xuống. Máy tính tiền khuyến mãi thì khác: máy phải <strong>kiểm tra một điều kiện</strong> rồi mới quyết định có in “Tang topping” hay không. Câu lệnh giúp máy làm việc này là <strong>câu lệnh if</strong> (if nghĩa là “nếu”).</p>
             <p>Ở chặng này, bạn sẽ chạy máy tính tiền với 5 ly, 2 ly và đúng 3 ly, xem dòng điều kiện cho kết quả đúng hay sai, rồi tìm ra vì sao khách mua đúng 3 ly bị bỏ sót và tự sửa lại.</p>`) + sauTab("Kiểm chứng") },
        { label: "Đoán rồi chạy", title: "Máy tính tiền với 5, 2 và 3 ly", tasks: ["c1-dc5", "c1-dc2", "c1-dc3"],
          html: huongDanDoan(3, true) + `<p>Ở dòng <code>if</code>, dòng code được tô <strong style="color:#166534">xanh</strong> khi điều kiện đúng và <strong style="color:#991b1b">đỏ</strong> khi điều kiện sai.</p>`,
          bit: "Để ý Lần 3: khách mua đúng 3 ly." },
        { label: "Kiểm chứng", title: "Khi nào câu lệnh trong { } được chạy?", tasks: ["c1-khoi", "c1-sau", "c1-moc"],
          code: TOPPING, focus: [7],
          html: `<p>Khung bên trái là máy tính tiền ở cả ba lần chạy. Dựa vào những gì bạn vừa thấy khi chạy từng dòng, trả lời các câu hỏi bên cạnh.</p>` },
        { label: "Ghi nhớ", title: "Câu lệnh if và phép so sánh",
          html: ghiVo(["<code>if (điều kiện) { … }</code>: điều kiện đúng thì chạy các câu lệnh trong <code>{ }</code>; sai thì bỏ qua cả khối.",
                "Câu lệnh đặt sau dấu <code>}</code> của khối if luôn chạy.",
                "“Từ 3 trở lên” viết <code>soLy &gt;= 3</code>; “trên 3” viết <code>soLy &gt; 3</code>."])
            + luuY("không đặt dấu <code>;</code> ngay sau <code>if (…)</code>. So sánh bằng viết hai dấu bằng <code>==</code>; một dấu <code>=</code> là phép gán.")
            + chiTiet
            + bang("1. Khái niệm", ["Thuật ngữ", "Định nghĩa", "Ví dụ"], [
              ["Câu lệnh rẽ nhánh", "Câu lệnh giúp chương trình chọn chạy hoặc bỏ qua một số câu lệnh, tuỳ theo một điều kiện.", "<code>if</code>, <code>if–else</code>"],
              ["Điều kiện", "Biểu thức cho kết quả <strong>đúng</strong> (true) hoặc <strong>sai</strong> (false), thường là một phép so sánh.", "<code>soLy &gt;= 3</code>"],
              ["Phép so sánh", "Phép toán so sánh hai giá trị, kết quả là đúng hoặc sai.", "<code>&gt;</code>, <code>&gt;=</code>, <code>==</code>"],
              ["Khối lệnh", "Nhóm câu lệnh nằm trong cặp ngoặc nhọn <code>{ }</code>, được chạy hoặc bỏ qua cùng nhau.", "<code>{ cout &lt;&lt; \"Tang topping\"; }</code>"],
              ["Giá trị mốc", "Số nằm ở ranh giới của quy tắc. Lỗi hay xảy ra đúng ở số mốc.", "Mốc 3 trong “từ 3 ly trở lên”"]])
            + bang("2. Sáu phép so sánh (với soLy = 3)", ["Phép so sánh", "Ý nghĩa", "Ví dụ", "Kết quả"], [
              ["<code>&gt;</code>", "lớn hơn (“trên”)", "<code>soLy &gt; 3</code>", "sai"],
              ["<code>&gt;=</code>", "lớn hơn hoặc bằng (“từ … trở lên”)", "<code>soLy &gt;= 3</code>", "đúng"],
              ["<code>&lt;</code>", "nhỏ hơn (“dưới”)", "<code>soLy &lt; 3</code>", "sai"],
              ["<code>&lt;=</code>", "nhỏ hơn hoặc bằng (“không quá”)", "<code>soLy &lt;= 3</code>", "đúng"],
              ["<code>==</code>", "bằng", "<code>soLy == 3</code>", "đúng"],
              ["<code>!=</code>", "khác", "<code>soLy != 3</code>", "sai"]])
            + bang("3. Chọn test case cho quy tắc có mốc", ["Test case", "Ví dụ với mốc 3", "Vì sao cần"], [
              ["Dưới mốc", "2 ly", "kiểm tra khách không đủ điều kiện"],
              ["Đúng mốc", "3 ly", "phát hiện nhầm <code>&gt;</code> với <code>&gt;=</code>"],
              ["Trên mốc", "4 ly", "kiểm tra khách đủ điều kiện"]])
            + scratch("if <(so ly) > [2]> then\nsay [Tang topping]\nend\nsay [Cam on quy khach!]", "Câu lệnh if giống khối <em>nếu … thì</em> trong Scratch.")
            + timThem([["https://www.w3schools.com/cpp/cpp_conditions.asp", "W3Schools · Câu lệnh if"],
                       ["https://www.w3schools.com/cpp/cpp_operators_comparison.asp", "W3Schools · Phép so sánh"],
                       ["https://www.programiz.com/cpp-programming/if-else", "Programiz · if, if…else"],
                       ["https://www.learncpp.com/cpp-tutorial/introduction-to-if-statements/", "LearnCpp · Câu lệnh if"]]) },
        { label: "Luyện tập", title: "Sửa máy tính tiền và kiểm thử đúng mốc", tasks: ["c1-sua"], html: BON_BUOC_1 },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        doanChay("c1-dc5", 1, 5, null, "5 > 3 đúng, nên máy chạy dòng 8 rồi chạy tiếp dòng 10.",
          "5 > 3 đúng, nên máy vào khối { } và in Tang topping (dòng 8), rồi chạy tiếp dòng 10 in lời cảm ơn."),
        doanChay("c1-dc2", 2, 2, "c1-dc5", "2 > 3 sai, nên máy bỏ qua dòng 8 nhưng vẫn in lời cảm ơn ở dòng 10.",
          "2 > 3 sai, nên máy bỏ qua cả khối { } (dòng 8). Dòng 10 nằm sau dấu } nên vẫn chạy."),
        doanChay("c1-dc3", 3, 3, "c1-dc2", "3 > 3 là sai, nên khách mua đúng 3 ly không được tặng. Lỗi của máy nằm ở đây!",
          "3 > 3 là sai: 3 bằng 3 chứ không lớn hơn 3. Vì vậy khách mua đúng 3 ly không được tặng topping. Đây chính là lỗi của máy tính tiền."),
        { id: "c1-khoi", type: "choice", icon: "🔍", title: "Dòng 8 chạy khi nào?",
          prompt: "Dòng 8 (<code>cout &lt;&lt; \"Tang topping\"</code>) nằm trong khối <code>{ }</code> của câu lệnh if. Dòng 8 chạy khi nào?",
          options: [
            { text: "Khi điều kiện ở dòng 7 đúng" },
            { text: "Luôn chạy, với mọi số ly", why: "Ở lần chạy với 2 ly, máy bỏ qua dòng 8: màn hình không có Tang topping." },
            { text: "Khi điều kiện ở dòng 7 sai", why: "Ở lần chạy với 5 ly, điều kiện đúng và máy chạy dòng 8." },
            { text: "Chỉ khi khách gõ đúng số 3", why: "Với 3 ly, 3 > 3 sai nên dòng 8 bị bỏ qua." }
          ],
          answer: "Khi điều kiện ở dòng 7 đúng", why: "Đúng. Điều kiện đúng thì máy chạy khối { }; sai thì bỏ qua cả khối." },
        { id: "c1-sau", type: "choice", icon: "🔍", title: "Dòng 10 chạy khi nào?",
          prompt: "Dòng 10 in lời cảm ơn <code>Cam on quy khach!</code>. Dòng này chạy khi nào?",
          options: [
            { text: "Chỉ khi khách được tặng topping", why: "Ở lần chạy với 2 ly, khách không được tặng nhưng máy vẫn in lời cảm ơn." },
            { text: "Luôn chạy, vì nằm sau dấu }" },
            { text: "Chỉ khi điều kiện ở dòng 7 sai", why: "Ở lần chạy với 5 ly, điều kiện đúng mà máy vẫn in lời cảm ơn." },
